const input = $input.first().json || {};

function safe(value, fallback = null) {
  return value === undefined || value === null || value === "" ? fallback : value;
}

function compactJson(value) {
  try {
    return JSON.stringify(value, null, 2);
  } catch (error) {
    return String(value);
  }
}

function fail({ code, message, details = [] }) {
  return [
    {
      json: {
        stop_before_http: true,
        success: false,
        component_id: "C4-E",
        component_version: "v1",
        event_id: input.input?.event_id || null,
        event_type: input.input?.event_type || null,
        email_draft: null,
        c4m_handoff: null,
        source_result: input.input || {},
        error: {
          code,
          message,
          details
        },
        next_action: "route_to_failure_log"
      }
    }
  ];
}

if (!input || Object.keys(input).length === 0) {
  return fail({
    code: "EMPTY_INPUT",
    message: "Input object is empty."
  });
}

if (!input.input || typeof input.input !== "object") {
  return fail({
    code: "MISSING_INPUT_OBJECT",
    message: "Input must include an input object."
  });
}

const source = input.input;
const config = input.config || {};

if (source.success !== true) {
  return fail({
    code: "UPSTREAM_ACTION_FAILED",
    message: "C4-E will not generate email draft when upstream action failed.",
    details: [{ upstream_component: source.component_id || null, upstream_error: source.error || null }]
  });
}

if (source.next_action !== "generate_email_draft") {
  return fail({
    code: "EMAIL_DRAFT_NOT_REQUESTED",
    message: "source.next_action is not generate_email_draft.",
    details: [{ next_action: source.next_action || null }]
  });
}

if (!config.email_type) {
  return fail({
    code: "MISSING_EMAIL_TYPE",
    message: "config.email_type is required."
  });
}

if (!config.email_goal) {
  return fail({
    code: "MISSING_EMAIL_GOAL",
    message: "config.email_goal is required."
  });
}

if (!config.client_ai_profile || typeof config.client_ai_profile !== "object") {
  return fail({
    code: "MISSING_CLIENT_AI_PROFILE",
    message: "config.client_ai_profile is required."
  });
}

if (!config.client_ai_profile.client_profile || !config.client_ai_profile.email_rules) {
  return fail({
    code: "INCOMPLETE_CLIENT_AI_PROFILE",
    message: "client_ai_profile must include at least client_profile and email_rules."
  });
}

if (!config.llm || typeof config.llm !== "object") {
  return fail({
    code: "MISSING_LLM_CONFIG",
    message: "config.llm is required."
  });
}

if (!config.llm.provider || !config.llm.endpoint || !config.llm.model) {
  return fail({
    code: "INCOMPLETE_LLM_CONFIG",
    message: "config.llm must include provider, endpoint, and model."
  });
}

if (config.llm.provider !== "groq") {
  return fail({
    code: "UNSUPPORTED_LLM_PROVIDER",
    message: "C4-E v1 demo supports provider = groq.",
    details: [{ provider: config.llm.provider }]
  });
}

const profile = config.client_ai_profile;
const emailRules = profile.email_rules || {};
const voiceProfile = profile.voice_profile || {};
const riskBoundaries = profile.risk_boundaries || {};
const approvalRules = profile.approval_rules || {};

const systemInstruction = [
  "You are a client-configured AI email drafting component inside an automation workflow.",
  "You generate drafts only. You do not send emails.",
  "Use only the provided lead/context and client profile.",
  "Do not invent facts, proof, case studies, pricing, revenue, guarantees, or urgency.",
  "Follow the client's voice, email rules, forbidden claims, and risk boundaries.",
  "Return valid JSON only. Do not include markdown fences."
].join(" ");

const outputSchema = {
  email_draft: {
    subject: "string",
    body: "string",
    cta: "string",
    email_type: config.email_type,
    personalization_used: ["string"],
    assumptions: ["string"],
    risk_flags: ["string"],
    approval_required: true
  }
};

const userContent = [
  "EMAIL TASK",
  compactJson({
    email_type: config.email_type,
    email_goal: config.email_goal,
    recipient_context: config.recipient_context || null,
    default_next_action: config.default_next_action || "package_draft_for_approval"
  }),
  "",
  "LEAD / SOURCE PAYLOAD",
  compactJson(source.payload || {}),
  "",
  "CLIENT AI PROFILE",
  compactJson(profile),
  "",
  "EMAIL RULES TO ENFORCE",
  compactJson({
    max_words: emailRules.default_max_words || 130,
    default_cta: emailRules.default_cta || "",
    must_include: emailRules.must_include || [],
    must_avoid: emailRules.must_avoid || [],
    personalization_allowed_fields: emailRules.personalization_allowed_fields || [],
    never_pretend_to_know: emailRules.never_pretend_to_know || [],
    phrases_to_avoid: voiceProfile.phrases_to_avoid || [],
    forbidden_claims: riskBoundaries.forbidden_claims || [],
    approval_policy: approvalRules.default_policy || "approval_required_before_external_action"
  }),
  "",
  "OUTPUT JSON SCHEMA",
  compactJson(outputSchema),
  "",
  "Return JSON only with the key email_draft."
].join("\n");

const body = {
  model: config.llm.model,
  messages: [
    {
      role: "system",
      content: systemInstruction
    },
    {
      role: "user",
      content: userContent
    }
  ],
  temperature: config.llm.temperature ?? 0.2,
  max_tokens: config.llm.max_tokens ?? 700,
  response_format: {
    type: "json_object"
  }
};

return [
  {
    json: {
      stop_before_http: false,
      request: {
        provider: config.llm.provider,
        endpoint: config.llm.endpoint,
        body
      },
      context: {
        component_id: "C4-E",
        component_version: "v1",
        event_id: source.event_id || null,
        event_type: source.event_type || null,
        email_type: config.email_type,
        email_goal: config.email_goal,
        client_ai_profile: profile,
        source_result: source,
        next_action: config.default_next_action || "package_draft_for_approval"
      }
    }
  }
];

const llmOutput = $input.first().json || {};
const prepared = $("Prepare Email Draft Request").first().json;
const context = prepared.context;

const content =
  llmOutput.choices?.[0]?.message?.content ??
  llmOutput.choices?.[0]?.text ??
  null;

let parsedJson = null;
let parseError = null;

if (content) {
  try {
    parsedJson = JSON.parse(content);
  } catch (error) {
    parseError = error.message;
  }
}

const emailDraft = parsedJson?.email_draft || null;

if (!emailDraft) {
  return [
    {
      json: {
        success: false,
        component_id: context.component_id,
        component_version: context.component_version,
        event_id: context.event_id,
        event_type: context.event_type,
        email_draft: null,
        c4m_handoff: null,
        source_result: context.source_result,
        error: {
          code: parseError ? "EMAIL_DRAFT_PARSE_FAILED" : "MISSING_EMAIL_DRAFT",
          message: parseError
            ? "LLM response could not be parsed as JSON."
            : "LLM response did not include email_draft.",
          details: [{ raw_content: content, parse_error: parseError }]
        },
        next_action: "route_to_failure_log"
      }
    }
  ];
}

const draftTitle = emailDraft.subject || `${context.email_type} email draft`;
const draftSummary = `Email draft generated for ${context.email_type}: ${draftTitle}`;

const c4mHandoff = {
  next_component: "C4-M",
  input: {
    success: true,
    component_id: "C4-E",
    component_version: "v1",
    event_id: context.event_id,
    event_type: "ai_email_draft",
    ai_result: {
      provider: prepared.request.provider,
      model: prepared.request.body.model,
      task_type: "email_draft",
      status: "completed",
      content,
      parsed_json: {
        draft_title: draftTitle,
        draft_summary: draftSummary,
        email_subject: emailDraft.subject || "",
        email_body: emailDraft.body || "",
        cta: emailDraft.cta || "",
        personalization_used: emailDraft.personalization_used || [],
        assumptions: emailDraft.assumptions || [],
        risk_flags: emailDraft.risk_flags || [],
        human_approval_required: true
      },
      usage: llmOutput.usage || null,
      finish_reason: llmOutput.choices?.[0]?.finish_reason || null
    },
    source_result: context.source_result,
    error: null,
    next_action: "request_approval"
  },
  config: {
    draft_type: "email",
    draft_status: "needs_review",
    approval_type: "email_review",
    reviewer_email: context.client_ai_profile?.approval_rules?.primary_reviewer_email || "",
    owner: "sales",
    priority: emailDraft.risk_flags?.length ? "high" : "normal",
    default_next_action: "request_approval"
  }
};

return [
  {
    json: {
      success: true,
      component_id: context.component_id,
      component_version: context.component_version,
      event_id: context.event_id,
      event_type: context.event_type,
      email_draft: {
        ...emailDraft,
        email_type: emailDraft.email_type || context.email_type,
        approval_required: true,
        provider: prepared.request.provider,
        model: prepared.request.body.model,
        usage: llmOutput.usage || null,
        finish_reason: llmOutput.choices?.[0]?.finish_reason || null
      },
      c4m_handoff: c4mHandoff,
      source_result: context.source_result,
      error: null,
      next_action: context.next_action
    }
  }
];

const prepared = $input.first().json || {};

return [
  {
    json: {
      success: prepared.success,
      component_id: prepared.component_id,
      component_version: prepared.component_version,
      event_id: prepared.event_id,
      event_type: prepared.event_type,
      email_draft: prepared.email_draft,
      c4m_handoff: prepared.c4m_handoff,
      source_result: prepared.source_result,
      error: prepared.error,
      next_action: prepared.next_action
    }
  }
];
